-- Obrazy sprzedajemy bez nazw odmian i bez podświetlenia: nowe tytuły i opisy.
-- Zmieniamy tylko, jeśli tytuł jest jeszcze ten z 0008 (Marcin mógł go już zmienić w panelu).
UPDATE "offers" SET "title" = 'Wzór 01', "description" = 'Pojedynczy koi płynący w dół, z gęstą siatką łusek i wachlarzem płetw, wycięty laserem w czarnej stalowej płycie. Prosty, spokojny wzór, który dobrze wygląda na jasnej ścianie albo z lampą za obrazem. Obraz sprzedajemy bez podświetlenia.' WHERE "id" = 'obraz-asagi' AND "title" = 'Asagi';--> statement-breakpoint
UPDATE "offers" SET "title" = 'Wzór 02', "description" = 'Duży koi w ciemne łaty, otoczony falami jak z japońskiego drzeworytu. To nasz najbardziej ażurowy wzór: przez gęsto wycięte fale i łuski pięknie przechodzi światło, jeśli powiesisz go na jasnej ścianie albo przed lampą. Obraz sprzedajemy bez podświetlenia.' WHERE "id" = 'obraz-showa-wsrod-fal' AND "title" = 'Showa wśród fal';--> statement-breakpoint
UPDATE "offers" SET "title" = 'Wzór 03', "description" = 'Dwa koi krążące wokół siebie, z długimi, falującymi płetwami. Układ przypomina yin i yang: ruch, równowagę i parę, która płynie razem. Dobry pomysł na prezent, np. na ślub, rocznicę albo nowe mieszkanie. Obraz sprzedajemy bez podświetlenia.' WHERE "id" = 'obraz-butterfly' AND "title" = 'Butterfly. Para koi';
